package com.amrshalaby.timesheet.timesheet;
import static org.junit.jupiter.api.Assertions.*; import org.junit.jupiter.api.Test; import java.time.*; import java.util.Map;
class MonthGridServiceTest { private final MonthGridService service=new MonthGridService(); @Test void buildsCompleteMondayToSundayRows(){ var grid=service.build(2026,8); assertEquals(DayOfWeek.MONDAY, grid.weeks().getFirst().days().getFirst().date().getDayOfWeek()); assertEquals(DayOfWeek.SUNDAY, grid.weeks().getLast().days().getLast().date().getDayOfWeek()); assertFalse(grid.weeks().getFirst().days().getFirst().inMonth()); } @Test void totalsIgnoreOutsideMonthCells(){ var grid=service.build(2026,8); var week=grid.weeks().getFirst().days(); assertEquals(60, TimesheetTotals.weeklyTotal(week, Map.of(LocalDate.of(2026,7,27), 999, LocalDate.of(2026,8,1), 60))); } }
